import re

_LOG_RE = re.compile(
    r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) \[(ERROR|WARN|INFO|DEBUG)\] (.+)$'
)


def parse_logs(logs):
    result = []
    for line in logs:
        m = _LOG_RE.match(line.strip())
        if not m:
            continue
        timestamp, level, rest = m.group(1), m.group(2), m.group(3)

        tokens = rest.split(' ')

        def is_kv_token(tok):
            key, sep, _ = tok.partition('=')
            return sep and key.isalnum()

        # Find the start of the trailing kv section: a token that is a
        # key= pair such that ALL tokens after it are also key= pairs.
        # This ensures kv pairs only come from the END of the line, so
        # prose containing '=' earlier in the message is left intact.
        kv_start = None
        for idx in range(len(tokens)):
            if is_kv_token(tokens[idx]) and all(
                is_kv_token(t) for t in tokens[idx + 1:]
            ):
                kv_start = idx
                break

        kv = {}
        if kv_start is None or kv_start == 0:
            message = rest.strip()
        else:
            message = ' '.join(tokens[:kv_start]).strip()
            current_key = None
            value_parts = []
            for token in tokens[kv_start:]:
                key, sep, val = token.partition('=')
                if sep and key.isalnum():
                    if current_key is not None:
                        kv[current_key] = ' '.join(value_parts)
                    current_key = key
                    value_parts = [val] if val else []
                else:
                    # Continuation of a multi-word value
                    value_parts.append(token)
            if current_key is not None:
                kv[current_key] = ' '.join(value_parts)

        result.append({
            'timestamp': timestamp,
            'level': level,
            'message': message,
            'kv': kv,
        })
    return result
